cc.Class({
    extends: cc.Component,

    properties:{
        wild_node:cc.Node,
        multiple_node:cc.Node,
        _symbols:[],
        _stickyIdxs:[], // 保存sticky wild idx 数据
        _isEnterWild:false, // 是否进入了wild游戏
    },

    onLoad() {
        this._symbolTemplate = SlotsFacade.dm.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this.wild_node.active = false;
        this.multiple_node.active = false;
    },

    /////////////////random Wild 相关///////////////
    /**
     * 显示随机wild
     * @param idxs
     * @returns {Promise<void>}
     */
    async showRandomWild(idxs) {
        this.wild_node.active = true;
        let colIdxArr = [[], [], [], [], []];
        for(let i=0; i<idxs.length; i++) {
            let idx = idxs[i];
            colIdxArr[(idx-1)%5].push(idx);
        }
        for(let colArr of colIdxArr) {
            if(colArr.length < 1) {
                continue;
            }
            for(let idx of colArr) {
                let symbol = this.genAWildSymbol(idx);
                symbol.playWildAppear();
                this._symbols.push(symbol);
            }
            SlotsFacade.soundMgr.playEffect("wild_appear");
            await SlotsFacade.delayTime(0.5);
        }
    },
    /////////////////MovingWild 相关///////////////
    /**
     * 添加移动的wild 请求下一个消息前调用
     * @returns {Promise<void>}
     */
    async _addMoveWild() {
        //找出新增的idx
        let moveWilds = SlotsFacade.dm.mapFreeInfo.moveWilds;
        let newIdxs = [];
        for(let i=0; i<moveWilds.currIdxs.length; i++) {
            let idx = moveWilds.currIdxs[i];
            if(moveWilds.randIdxs.includes(idx)) {
                continue;
            }
            newIdxs.push(idx);
        }
        this.wild_node.active = true;
        for(let i=0; i<newIdxs.length; i++) {
            let symbol = this.genAWildSymbol(newIdxs[i]);
            this._symbols.push(symbol);
        }
    },

    /**
     * 移动wild 请求消息后调用
     * @returns {Promise<void>}
     * @private
     */
    async _moveWild() {
        SlotsFacade.soundMgr.playEffect("wild_move");
        let moveWilds = SlotsFacade.dm.mapFreeInfo.moveWilds;
        this.wild_node.active = true;
        for(let i=0; i<this._symbols.length; i++) {
            let idx = moveWilds.randIdxs[i];
            let symbol = this._symbols[i];
            if(idx && symbol) {
                let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
                pos = this.wild_node.convertToNodeSpaceAR(pos);
                cc.tween(symbol.node).to(0.8, {x:pos.x, y:pos.y}).start();
            }else {
                console.log("move wild 数据异常", moveWilds, symbol);
            }
        }
        if(this._symbols.length >0) {
            SlotsFacade.soundMgr.playEffect("moving_wild");
        }
        await SlotsFacade.delayTime(0.8);
    },


    /////////////////StickyWild 相关///////////////
    /**
     * 添加 sticky wild
     * @private
     */
    _addStickyWild() {
        let idxs = SlotsFacade.dm.mapFreeInfo.stickyWilds;
        this.wild_node.active = true;
        for(let i=0; i<idxs.length; i++) {
            if(this._stickyIdxs.includes(idxs[i])) {
                continue;
            }
            let symbol = this.genAWildSymbol(idxs[i]);
            this._symbols.push(symbol);
            this._stickyIdxs.push(idxs[i]);
        }
    },

    /////////////////MultSlot 相关///////////////
    /**
     * 初始化多倍wild资源
     * @returns {Promise<void>}
     * @private
     */
    async _initMulWild() {
        //移除中间列的triggerAnimation以免遮挡倍数wild动画
        let idxs = [3,8,13, 18,23,28, 33,38,43];
        for(let idx of idxs) {
            SlotsFacade.slots.GetSymbolByIdx(idx).StartMove();
        }

        this.multiple_node.active = true;
        for(let i=0; i<3; i++) {
            let node = this.multiple_node.getChildByName(`mul${i+1}`);
            let spine_wild = node.getChildByName("spine_wild").getComponent(sp.Skeleton);
            spine_wild.node.active = true;
            spine_wild.setAnimation(0, "animation5", false);
            let spine_mask = node.getChildByName("spine_mask").getComponent(sp.Skeleton);
            spine_mask.node.active = true;
            spine_mask.setAnimation(0, "animation4", false);
        }
    },

    /**
     * 展开 mul wild
     * @returns {Promise<void>}
     * @private
     */
    async _expansionMulWild() {
        SlotsFacade.soundMgr.playEffect("wild_open");
        let multWilds = SlotsFacade.dm.mapFreeInfo.multWilds;
        for(let i=0; i<3; i++) {
            let node = this.multiple_node.getChildByName(`mul${i+1}`);
            let spine_mask = node.getChildByName("spine_mask").getComponent(sp.Skeleton);
            spine_mask.node.active = true;
            spine_mask.setAnimation(0, "animation1", false);
            let label = node.getChildByName("label").getComponent(cc.Label);
            label.string = `${multWilds[i]}X`;
            label.node.scale = 0;
            cc.tween(label.node).delay(0.3).to(0.5, {scale:1}, {easing:"backOut"}).start();
        }
        await SlotsFacade.delayTime(0.8);
    },

    /**
     * 折叠 mul wild
     * @returns {Promise<void>}
     * @private
     */
    async _collapseMulWild() {
        for(let i=0; i<3; i++) {
            let node = this.multiple_node.getChildByName(`mul${i+1}`);
            let spine_mask = node.getChildByName("spine_mask").getComponent(sp.Skeleton);
            spine_mask.node.active = true;
            if(spine_mask.animation == "animation4") {
                continue;
            }
            spine_mask.setAnimation(0, "animation3", false);
            spine_mask.addAnimation(0, "animation4", false);
        }
        // 隐藏symbol动画
        let idxs = [3,8,13, 18,23,28, 33,38,43];
        for(let i of idxs) {
            SlotsFacade.slots.GetSymbolByIdx(i).StartMove();
        }
        await SlotsFacade.delayTime(0.8);
    },

    /**
     * 播放 mul wild 动画
     * @param needSkipAniIdxs
     */
    playWinMulAni(needSkipAniIdxs) {
        let flagArr = [false, false, false];
        for(let idx of needSkipAniIdxs) {
            flagArr[Math.floor(idx/15)] = true;
        }

        for(let i=0; i<flagArr.length; i++) {
            let spine = cc.find(`mul${i+1}/spine_wild`, this.multiple_node).getComponent(sp.Skeleton);
            if(flagArr[i]) {
                spine.setAnimation(0, "animation2", true);
            }else {
                spine.setAnimation(0, "animation5", false);
            }
        }
    },

    /////////////////wild game 流程相关///////////////
    /**
     * 生成一个wild图标
     * @param {*} idx
     */
    genAWildSymbol(idx) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplate)
        node.parent = this.wild_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(0);
        scp.Init(0, this.node);
        scp.ShowById(cfg.wildId);
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return scp;
    },

    /**
     * 进入wild game
     * @returns {Promise<void>}
     */
    async enterWildGame() {
        let mapInfo = SlotsFacade.dm.energyData;
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let mapType = SlotsFacade.dm.getGameCfg().MapType;
        let mapItem = mapCfg[mapInfo.currId];
        if(mapItem.type == mapType.MultSlot) {
            this._initMulWild();
        }else if(mapItem.type == mapType.MovingWild) {
            //
        }else if(mapItem.type == mapType.RandomWild) {
            //
        }else if(mapItem.type == mapType.StickyWild) {
        }
        this._isEnterWild = true;
    },

    /**
     * 退出wild game
     * @returns {Promise<void>}
     */
    async exitWildGame() {
        let mapInfo = SlotsFacade.dm.energyData;
        let currId = mapInfo.currId;
        if(mapInfo.currId == 0) {
            currId = SlotsFacade.dm.getGameCfg().TheFinalHurdleID;
        }
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let mapType = SlotsFacade.dm.getGameCfg().MapType;
        let mapItem = mapCfg[currId];
        if(mapItem.type == mapType.MultSlot) {
            this.multiple_node.active = false;
        }else if(mapItem.type == mapType.MovingWild) {
            this.removeWild();
        }else if(mapItem.type == mapType.RandomWild) {
            this.removeWild();
        }else if(mapItem.type == mapType.StickyWild) {
            this.removeWild();
        }
        this._isEnterWild = false;
    },

    /**
     * 移除wild
     */
    removeWild() {
        this._symbols = [];
        this._stickyIdxs = [];
        this.wild_node.active = false;
        this.wild_node.removeAllChildren();
    },

    /**
     * 隐藏wild
     */
    hideWild() {
        this.wild_node.active = false;
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async startMove() {
        let mapInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(mapInfo.state != 2) {
            return false;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }

        if(!SlotsFacade.dm.mapFreeInfo) {
            return;
        }
        let currId = mapInfo.currId;
        if(mapInfo.currId == 0) {
            currId = SlotsFacade.dm.getGameCfg().TheFinalHurdleID;
        }
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let mapType = SlotsFacade.dm.getGameCfg().MapType;
        let mapItem = mapCfg[currId];
        if(mapItem.type == mapType.RandomWild) {
            //
        }else if(mapItem.type == mapType.MultSlot) {
            this._collapseMulWild();
        }else if(mapItem.type == mapType.MovingWild) {
            this._addMoveWild();
        }else if(mapItem.type == mapType.StickyWild) {
            this._addStickyWild();
        }
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        let mapInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(mapInfo.state != 2) {
            return;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }

        let currId = mapInfo.currId;
        if(mapInfo.currId == 0) {
            currId = SlotsFacade.dm.getGameCfg().TheFinalHurdleID;
        }
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let mapType = SlotsFacade.dm.getGameCfg().MapType;
        let mapItem = mapCfg[currId];
        if(mapItem.type == mapType.RandomWild) {
            await this.showRandomWild(SlotsFacade.dm.mapFreeInfo.randomWilds);
        }else if(mapItem.type == mapType.MultSlot) {
            //
        }else if(mapItem.type == mapType.MovingWild) {
            await this._moveWild();
        }else if(mapItem.type == mapType.StickyWild) {
            //
        }
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        let mapInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(mapInfo.state != 2) {
            return;
        }
        if(!this._isEnterWild) {
            console.log("未在wild game 中直接返回");
            return;
        }
        let currId = mapInfo.currId;
        if(mapInfo.currId == 0) {
            currId = SlotsFacade.dm.getGameCfg().TheFinalHurdleID;
        }
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let mapType = SlotsFacade.dm.getGameCfg().MapType;
        let mapItem = mapCfg[currId];
        if(mapItem.type == mapType.RandomWild) {
            this.removeWild();
        }else if(mapItem.type == mapType.MultSlot) {
            await this._expansionMulWild();
        }else if(mapItem.type == mapType.MovingWild) {
            await this.hideWild();
        }else if(mapItem.type == mapType.StickyWild) {
            await this.hideWild();
        }
    },
 })