let CollectGameMap = cc.Class({
    extends: cc.Component,

    properties: {
        callBack:null,
        panel:null,
        bg:null,
        btn_close:null,
        scrollView:null,
        map_flag:null,
        mapItems:[],
    },

    onLoad() {
        this._initView();
        this._initListener();
    },

    _initView() {
        this.panel = this.node.getChildByName("panel");
        this.bg = this.node.getChildByName("bg");
        this.btn_close = this.panel.getChildByName("btn_close").getComponent(cc.Button);
        this.scrollView = this.panel.getChildByName("scrollview").getComponent(cc.ScrollView);
        this.map_flag = this.scrollView.content.getChildByName("map_flag");
        this.map_flag.originPos = {x:this.map_flag.x, y:this.map_flag.y};
        this.mapItems = [];
        for(let i=1; i<=33; i++) {
            let item = this.scrollView.content.getChildByName("item" + i);
            item["id"] = i;
            this.mapItems.push(item);
            this.markItemState(i, true);
        }
        this._reset();
    },

    /**
     * 当通过最后一关后需要重置地图
     */
    resetMap() {
        this.map_flag.x = this.map_flag.originPos.x;
        this.map_flag.y = this.map_flag.originPos.y;

        for(let i=0; i<this.mapItems.length; i++) {
            this.markItemState(i+1, true);
        }
    },

    _initListener() {
        this.btn_close.node.on("click", this._onBtnCloseHandler.bind(this), this);
    },

    /**
     * 显示关闭按钮
     * @returns {Promise<unknown>}
     * @private
     */
    _showCloseBtn() {
        return new Promise((res)=> {
            this.btn_close.node.active = true;
            this.btn_close.node.scale = 0;
            this.btn_close.interactable = true;
            cc.tween(this.btn_close.node)
                .to(0.3, {scale:1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    async _onBtnCloseHandler() {
        SlotsFacade.soundMgr.playEffect("click");
        this.btn_close.interactable = false;
        cc.tween(this.btn_close.node)
            .to(0.3, {scale:0}, {easing:"backIn"})
            .call(()=>{
                this.exitMap(true);
            })
            .start();
    },

    _exitProcess() {
        this._reset();
        if(SlotsFacade.dm.energyData.currId == SlotsFacade.dm.getGameCfg().TheFinalHurdleID) {
            this.resetMap();
        }
        this.panel.active = false;
        if(this.callBack) {
            this.callBack();
            this.callBack = null;
        }
    },

    /**
     * 退出
     */
    exitMap(isView) {
        isView = isView || false;
        SlotsFacade.soundMgr.playEffect("map_close");
        this.bg.active = false;
        if(isView) {
            cc.tween(this.panel)
                .to(0.3, {y:this.node.height/2}, {easing:"cubicOut"})
                .call(()=>{
                    this._exitProcess();
                })
                .start();
        }else {
            this._exitProcess();
        }
    },

    /**
     * 进入
     * @param isView 是否是查看
     * @param cb
     * @returns {Promise<void>}
     */
    async enterMap(isView, cb) {
        SlotsFacade.soundMgr.playEffect("map_open");
        this.callBack = cb;
        this.node.active = true;
        this.panel.active = true;
        this.panel.opacity = 0;

        // 延迟一帧执行 保证依赖widget的逻辑正常
        await new Promise(res=>{
            this.scheduleOnce(()=>{
                res();
            })
        })

        this.panel.opacity = 0xff;
        this.panel.y = this.node.height/2;
        let data = SlotsFacade.dm.energyData;
        let currIndex = data.currId;
        if(!isView && data.state > 0) {
            currIndex -= 1;
        }
        this._freshMap(currIndex);

        // 黑色背景慢慢显示
        this.bg.active = true;
        this.bg.opacity = 0;
        cc.tween(this.bg)
            .to(0.4, {opacity:200})
            .start();
        await SlotsFacade.delayTime(0.3);
        // 整个panel往下移动
        await new Promise(res=>{
            cc.tween(this.panel)
                .to(0.35, {y:-this.node.height/2})
                .call(()=>{
                    res();
                })
                .start();
        })

        // 移动地图
        if(currIndex > 0) {
            let centerY = -(this.scrollView.content.height - this.scrollView.node.height/2);
            let maxOffsetY = this.scrollView.getMaxScrollOffset().y;
            let item = SlotsFacade.map.mapItems[currIndex-1];
            this.scrollView.scrollToOffset(cc.v2(0, maxOffsetY-(item.y-centerY)), 1);
        }else {
            this.scrollView.scrollToBottom();
        }
        if (isView) {
            this._showCloseBtn();
        }else {
            SlotsFacade.collectProgress.setProgress(0);
            await this._moveMapFlag(data.currId);
            await SlotsFacade.delayTime(1);
            let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
            let vo = mapCfg[data.currId];
            switch(vo.type) {
                case 1:
                    SlotsFacade.slots777.showEnter(SlotsFacade.dm.energyData.startPrice);
                    this.exitMap();
                    break;
                case 2:
                case 3:
                case 4:
                case 5:
                    let mapInfo = SlotsFacade.dm.energyData;
                    let mapItem = SlotsFacade.dm.getGameCfg().mapCfg[mapInfo.currId + ""];
                    let mul1 = 0;
                    let mul2 = 0;
                    if(mapItem.type == SlotsFacade.dm.getGameCfg().MapType.MultSlot) {
                        mul1 = mapItem.min;
                        mul2 = mapItem.max;
                    }
                    await SlotsFacade.popup.showWinMapFreeCnt(mapItem.type, mul1, mul2);
                    await SlotsFacade.mainPanel.showSceneTransition(3);
                    this.exitMap();
                    break;
            }
        }
    },

    /**
     * 移动地图标记
     * @param toIdx
     * @private
     */
    async _moveMapFlag(toIdx) {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[toIdx.toString()];
        let item = this.mapItems[toIdx-1];
        // 角色移动动画
        await new Promise((res)=> {
            // let spine = this.map_flag.getChildByName("spine").getComponent(sp.Skeleton);
            // spine.setAnimation(0, "animation2", false);
            // spine.addAnimation(0, "animation", true);
            SlotsFacade.soundMgr.playEffect("ui_move");
            cc.tween(this.map_flag)
                .to(0.4, {x:item.x, y:item.y})
                .call(()=>{
                    res();
                })
                .start();
        });

        let cfg = SlotsFacade.dm.getGameCfg();
        // 播放动画
        let itemContent = item.getChildByName(`type${vo.type}`);
        if(vo.type == cfg.MapType.MultSlot) {
            itemContent = itemContent.getChildByName(`item${vo.level}`);
        }
        if(vo.type == cfg.MapType.SevenSlot) {
            SlotsFacade.soundMgr.playEffect("small_trigger");
            let spine = itemContent.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, vo.iconAni, true);
        }else {
            SlotsFacade.soundMgr.playEffect("big_trigger");
            let coin = itemContent.getChildByName("coin");
            coin.active = true;
            let spine = coin.getChildByName("spine").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation2", true);
        }
    },

    _freshMap(currIndex) {
        for(let i=1; i<=currIndex; i++) {
            this.markItemState(i, false);
        }
        if(currIndex > 0) {
            let item = this.mapItems[currIndex-1];
            this.map_flag.position = item.position;
        }
    },

    /**
     * 标记item状态
     */
    markItemState(index, isActive) {
        isActive = isActive || false;
        let cfg = SlotsFacade.dm.getGameCfg();
        let vo = cfg.mapCfg[index.toString()];
        let item = this.mapItems[index-1];
        let itemContent = item.getChildByName(`type${vo.type}`);
        if(vo.type == cfg.MapType.MultSlot) {
            itemContent = itemContent.getChildByName(`item${vo.level}`);
        }
        if(vo.type == cfg.MapType.SevenSlot) {
            itemContent.getChildByName("spine").active = false;
            let img = itemContent.getChildByName("icon").getComponent("ImgSwitchCmp");
            if (isActive) {
                img.setIndex(vo.iconIndex);
            } else {
                img.setIndex(0);
            }
        }else {
            let coin = itemContent.getChildByName("coin");
            if(isActive) {
                coin.active = true;
                let spine = coin.getChildByName("spine").getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "animation1", true);
            }else {
                coin.active = false;
            }
        }
    },

    /**
     * 重置
     */
    _reset() {
        this.panel.active = false;
        this.scrollView.node.y = this.scrollView.node.height/2;
        this.btn_close.node.active = false;
        this.node.active = false;
    },
});
