cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _reelBg:cc.Node,
    },

    onLoad () {
        this._super();
    },

    /**
     *
     * @returns {*[]}
     * @constructor
     */
    GetResizeHeightObjs:function(){
        let objs = [];
        let mask = cc.find("mask",this.node)
        if(mask){
            objs.push(mask)
        }
        if(this._reelBg) {
            objs.push(this._reelBg);
        }else {
            let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
            if(bg){
                objs.push(bg)
            }
        }
        return objs
    },

    /**
     * 设置背景资源
     * @param reelBg
     */
    bindReelBg(reelBg) {
        if(reelBg) {
            this._reelBg = reelBg;
        }
    },

    /**
     * 是否需要加速
     */
    isNeedAddSpeed() {
        for (let info of this._reelState) {
            if (info.isAnt) {
                return true;
            }
        }
        return false;
    }
})
