/**
 * 多卷轴配置
 */
let MulSlotCfg = {
    maxSlotCnt: 3,       // 最大slot数量
    currSlotCnt: 1,      // 当前slot数量
    unitSlotRowCnt: 3,   // 单个slot 行数
    unitSlotColCnt: 5,   // 单个slot 列数
    aSlotSymbolCnt: 15,  // 一个slots 的symbol个数
}

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        allReels: [], // 保存所有reel组件

        reels_bg: cc.Node,           // reel 背景
        reels_frame: cc.Node,        // reel 框
    },

    onLoad() {
        this._super();
        this.reels_bg = this.node.getChildByName("reels_bg");
        this.reels_frame = this.node.getChildByName("reels_frame");
    },

    /**
     * 创建卷轴
     * @override
     * @param col
     * @param row
     */
    createReels: function (col, row) {
        let reelCmp = this._cfg.scripts.Reels
        for (let i = 0; i < col; i++) {
            let node = null;
            let reelBg = null;
            if (i == 10) {
                node = cc.find(`bonus_game_node/panel/reel1_mask/reel${i + 1}`, this.node);
                reelBg = cc.find(`bonus_game_node/panel/reel1_mask/reel_bg${i + 1}`, this.node);
            } else if (i > 10) {
                node = cc.find(`bonus_game_node/panel/reels/reel${i + 1}`, this.node);
                reelBg = cc.find(`bonus_game_node/panel/reels/reel_bg${i + 1}`, this.node);
            } else {
                node = cc.find(`reels/reel${i + 1}`, this.node);
            }
            let scp = node.addComponent(reelCmp)
            scp.Init(i, row, this._topAniNode);
            if (reelBg) {
                scp.bindReelBg(reelBg);
            }
            this.allReels.push(scp)
        }
    },

    /**
     * @override
     */
    StartMove: function () {
        this._bStopRightnow = null
        this._gameInfo = null
        SlotsFacade.flowCtrl.startMove();
        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this.getCurReels());  //Changed ...

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime();
        if (SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
        SlotsFacade.collectProgress.setEnterEnable(false);
    },

    /**
     * @override
     * @param {*} msg 
     */
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },


    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow: function () {
        this.scheduleOnce(() => {
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * [0~15)第一个卷轴 [15~30)第二个卷轴 [30~45)第二个卷轴
     * @override
     * @param {*} cards 
     */
    SetSlotsResult: function (cards) {
        let reelResults = [];
        for (let i = 0; i < MulSlotCfg.currSlotCnt; i++) {
            let startIndex = i * MulSlotCfg.unitSlotColCnt * MulSlotCfg.unitSlotRowCnt;
            let endIndex = startIndex + MulSlotCfg.unitSlotColCnt * MulSlotCfg.unitSlotRowCnt;
            for (let j = startIndex; j < endIndex; j++) {
                let col = i * MulSlotCfg.unitSlotColCnt + j % MulSlotCfg.unitSlotColCnt;
                // if(this._cfg.symbol[cards[j]]){
                let res = {};
                res.sid = cards[j];
                if (!reelResults[col]) {
                    reelResults[col] = [];
                }
                reelResults[col].unshift(res);
                // }else {
                //     console.log("未知卷轴：", cards[j]);
                // }
            }
        }

        // 设置bonus数据 多卷轴不需要处理
        let bonusItem = null;
        if (SlotsFacade.dm.belleBonus) {
            if (SlotsFacade.dm.belleBonus.bonusInfo) {
                bonusItem = SlotsFacade.dm.belleBonus.bonusInfo.items;
            }
        } else if (SlotsFacade.dm.getSpinData().bonusInfo) {
            if (SlotsFacade.dm.isTriggerNormalBonus()) {
                bonusItem = SlotsFacade.dm.getSpinData().bonusInfo.items;
            } else {
                bonusItem = SlotsFacade.dm.getSpinData().bonusInfo.extraItems;
            }
        }
        if (bonusItem) {
            let bi = []
            if (Array.isArray(bonusItem)) { bi = bonusItem }
            for (let item of bi/*bonusItem*/) {
                let idxInfo = this.transferIdx(item.idx);
                reelResults[idxInfo.col][idxInfo.row].data = { coin: item.coin };
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    /**
     * @override
     * @param {*} cards
     */
    SetReelStateInfo: function (cards) {
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = [];
        for (let i = 0; i < cards.length; i++) {
            let id = cards[i];
            let col = Math.floor(i / MulSlotCfg.aSlotSymbolCnt) * MulSlotCfg.unitSlotColCnt + i % MulSlotCfg.unitSlotColCnt;
            if (!reelResults[col]) {
                reelResults[col] = [];
            }
            reelResults[col].push(id);
        }
        let rsi = []
        if (Array.isArray(this._cfg.reelStateInfo)) { rsi = this._cfg.reelStateInfo}
        for (let info of rsi/*this._cfg.reelStateInfo*/) {
            for (let i = 0; i < MulSlotCfg.currSlotCnt; i++) {
                let stateInfo = Global.copy(info);
                stateInfo.isStop = false;
                stateInfo.isAnt = false;
                let triggerCount = stateInfo.mini;
                let countsConfig = Global.copy(stateInfo.counts);
                let haveCount = 0;
                let startIndex = i * MulSlotCfg.unitSlotColCnt;
                let endIndex = startIndex + MulSlotCfg.unitSlotColCnt;
                for (let j = startIndex; j < endIndex; j++) {
                    let reelRes = reelResults[j];
                    stateInfo.isStop = false;
                    stateInfo.isAnt = false;
                    if (haveCount >= triggerCount - 1 && stateInfo.counts[j % MulSlotCfg.unitSlotColCnt] > 0) {  //满足条件 需要播放加速框
                        stateInfo.isAnt = true;
                    }
                    let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                    haveCount += reelCountOfID;
                    countsConfig.shift();
                    let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x, y) => x + y) : 0) + haveCount;
                    if (reelCountOfID > 0 && remainingCount >= triggerCount) {  //满足条件 播放停止动画和停止音效
                        stateInfo.isStop = true;
                    }
                    stateInfo.symbolStopSound = `scatter_land${1 + haveCount % 3}`;
                    let item = this._reels[j];
                    item.AddReelStateInfo(Global.copy(stateInfo));
                }
            }
        }
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx - 1;
        let col = Math.floor(idx / MulSlotCfg.aSlotSymbolCnt) * MulSlotCfg.unitSlotColCnt + idx % MulSlotCfg.unitSlotColCnt;
        let row = MulSlotCfg.unitSlotRowCnt - 1 - Math.floor(idx % MulSlotCfg.aSlotSymbolCnt / MulSlotCfg.unitSlotColCnt);
        return { col: col, row: row };
    },

    /**
     * @override
     * @param {*} idx 服务器symbol下标1开始
     */
    GetSymbolByIdx(idx) {
        let idxInfo = this.transferIdx(idx);
        return this._reels[idxInfo.col].GetSymbolByRow(idxInfo.row);
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * @override
     * @param {*} reelIdx 
     */
    GetReelStopInter(reelIdx) {
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx % MulSlotCfg.unitSlotColCnt * nIter;
    },

    /**
     * @override
     * @param {*} dt 
     */
    update(dt) {
        if (this._stopTime > 0) {
            this._stopTime = this._stopTime - dt
            if (this._stopTime <= 0) { //空转时间到了
                if (this.CanStopSlot()) {//满足开始停止的条件
                    let belleBonus = SlotsFacade.dm.belleBonus;
                    let bonusTime = 0;
                    if (belleBonus && belleBonus.bonusInfo || SlotsFacade.dm.isTriggerNormalBonus()) {
                        bonusTime = 5;
                    } else {
                        this._bottomScript.ShowBtnsByState("moveing_2");
                    }
                    //倒计时完，设置一次
                    for (let i = 0; i < this._reels.length; i++) {
                        let item = this._reels[i]
                        let reelStopInterv = this.GetReelStopInter(i)
                        if (bonusTime > 0) {
                            if (i > 0) {
                                reelStopInterv = reelStopInterv + bonusTime + 2 * (i - 1);
                            }
                        }
                        item.StopMove(reelStopInterv)
                    }
                }
                else {
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt

                    //记录一个超时时间.
                    this._roundSpineTime = this._roundSpineTime || 0
                    this._roundSpineTime += dt
                    if (this._roundSpineTime > 30) {
                        // this._stopTime = -1 
                        this._topScript.SetBackLobby(true)
                    }
                }

            }
        }
    },

    /**
     * 显示中奖路线
     * @override
     */
    ShowWinTrace: function () {
        let allWinIdx = []
        //中奖位置
        let zjLuXian = SlotsFacade.dm.getZjLuXian();
        for (let i = 0; i < zjLuXian.length; i++) {
            let item = zjLuXian[i]
            for (let idx = 0; idx < item.indexs.length; idx++) {
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        let skipBorderAniIdxs = [];
        if (this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs) {
            for (let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++) {
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
            let idx = this._gameInfo && this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs
            if (!Array.isArray(idx)) { idx = [] }
            skipBorderAniIdxs = idx.concat();
        }

        // 处理地图免费游戏中不动两列的symbol
        let needSkipAniIdxs = [];
        if (SlotsFacade.dm.energyData.state == 2 && !SlotsFacade.dm.isFistTriggerFree()) {
            let cfg = SlotsFacade.dm.getGameCfg();
            let currMapItem = cfg.mapCfg[SlotsFacade.dm.energyData.currId];
            if (currMapItem && currMapItem.type == cfg.MapType.MultSlot) {
                let skipIdxs = [3, 8, 13, 18, 23, 28, 33, 38, 43];
                for (const key in allWinIdx) {
                    if (skipIdxs.includes(Number(key))) {
                        needSkipAniIdxs.push(Number(key));
                    }
                }
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if (symbol) {
                if (!needSkipAniIdxs.includes(Number(key))) {
                    symbol.playWinAnimation()
                }
                if (!skipBorderAniIdxs.includes(Number(key))) {
                    symbol.ShowKuang();
                }
            }
        }

        if (needSkipAniIdxs.length > 0) {
            SlotsFacade.wildGame.playWinMulAni(needSkipAniIdxs);
        }
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 清楚播放状态
     */
    cleanPlayState() {
        this._reels.forEach(reel => {
            reel._symbols.forEach(symbol => {
                symbol.cleanPlayState();
            })
        })
    },

    /**
     * 返回当前有效得reels 请求消息前调用
     */
    getCurReels() {
        let skipColIdx = [];
        if (SlotsFacade.dm.energyData.state == 2 && SlotsFacade.dm.hasFree()) {
            let cfg = SlotsFacade.dm.getGameCfg();
            let currMapItem = cfg.mapCfg[SlotsFacade.dm.energyData.currId];
            if (currMapItem && currMapItem.type == cfg.MapType.MultSlot) {
                skipColIdx = [2, 7, 12];
            }
        }
        if (skipColIdx.length > 0) {
            let ret = [];
            for (let i = 0; i < this._reels.length; i++) {
                if (skipColIdx.includes(i)) {
                    continue;
                }
                ret.push(this._reels[i]);
            }
            return ret;
        } else {
            return this._reels;
        }
    },

    /**
     * 返回当前有效reels个数
     */
    getCurrReelCnt() {
        return MulSlotCfg.currSlotCnt * MulSlotCfg.unitSlotColCnt;
    },

    /**
     * 更具下标设置 reel 的 reel state
     * @param idx
     * @param boo
     */
    setReelStopState(idx, boo) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let symbolId = SlotsFacade.dm.getSpinData().resultCards[idx - 1];
        let rs = []
        if (Array.isArray(reel._reelState)) { rs = reel._reelState }
        for (let info of rs/*reel._reelState*/) {
            if (info.id.includes(symbolId)) {
                info.isStop = boo;
            }
        }
    },

    /**
     * 切换到普通游戏状态
     */
    toNormalState() {
        SlotsFacade.character.show();
        SlotsFacade.character.toNormalState();
        SlotsFacade.collectProgress.show();
        SlotsFacade.bagGame.show();
        SlotsFacade.jackpot.show();

        this.reels_frame.active = true;
        MulSlotCfg.currSlotCnt = 1;
        MulSlotCfg.unitSlotRowCnt = 3;
        MulSlotCfg.aSlotSymbolCnt = 15;
        for (let i = 0; i < 10; i++) {
            this.allReels[i].node.active = false;
            this.reels_bg.getChildByName(`reel_bg${i + 1}`).active = false;
        }
        this.reels_frame.getChildByName(`frame1`).active = false;
        this.reels_frame.getChildByName(`frame2`).active = false;
        this._reels = this.allReels.slice(15 - 5, 15);
        let r = []
        if (Array.isArray(this._reels)) { r = this._reels }
        // 重置行数
        for (let reel of r/*this._reels*/) {
            if (reel._nCount != 3) {
                reel.AddCount(3 - reel._nCount, 0.001);
            }
        }
        this.node.scale = 1;
        SlotsFacade.bonusGame.toNormalState();
    },

    /**
     * 切换到地图免费游戏
     */
    toMapFreeState() {
        SlotsFacade.character.hide();
        SlotsFacade.collectProgress.hide();
        SlotsFacade.bagGame.hide();
        SlotsFacade.jackpot.hide();

        this.reels_frame.active = true;
        MulSlotCfg.currSlotCnt = 3;
        MulSlotCfg.unitSlotRowCnt = 3;
        MulSlotCfg.aSlotSymbolCnt = 15;
        for (let i = 0; i < 10; i++) {
            this.allReels[i].node.active = true;
            this.reels_bg.getChildByName(`reel_bg${i + 1}`).active = true;
        }
        this.reels_frame.getChildByName(`frame1`).active = true;
        this.reels_frame.getChildByName(`frame2`).active = true;
        this._reels = this.allReels.concat();
        this.node.scale = 0.8;
    },

    /**
     * 切换到转盘免费游戏
     */
    toWheelFreeState() {
        SlotsFacade.character.show();
        SlotsFacade.character.toWheelFreeState();
        SlotsFacade.collectProgress.hide();
        SlotsFacade.bagGame.hide();
        SlotsFacade.jackpot.hide();

        this.reels_frame.active = false;
        MulSlotCfg.currSlotCnt = 1;
        MulSlotCfg.unitSlotRowCnt = 5;
        MulSlotCfg.aSlotSymbolCnt = 25;
        for (let i = 0; i < 10; i++) {
            this.allReels[i].node.active = false;
            this.reels_bg.getChildByName(`reel_bg${i + 1}`).active = false;
        }
        this._reels = this.allReels.slice(15 - 5, 15);
        let r = []
        if (Array.isArray(this._reels)) { r = this._reels }
        // 添加行数
        for (let reel of r/*this._reels*/) {
            if (reel._nCount != 5) {
                reel.AddCount(5 - reel._nCount, 0.001);
            }
        }
        SlotsFacade.bonusGame.toWheelFreeState();
        this.node.scale = 1;
    },

    /**
     * 切换到转盘免费bonus游戏
     */
    toWheelBonusState() {
        SlotsFacade.character.show();
        SlotsFacade.character.toNormalState();
        SlotsFacade.collectProgress.hide();
        SlotsFacade.bagGame.hide();
        // SlotsFacade.jackpot.hide();

        this.reels_frame.active = true;
        MulSlotCfg.currSlotCnt = 1;
        MulSlotCfg.unitSlotRowCnt = 6;
        MulSlotCfg.aSlotSymbolCnt = 30;
        for (let i = 0; i < 10; i++) {
            this.allReels[i].node.active = false;
            this.reels_bg.getChildByName(`reel_bg${i + 1}`).active = false;
        }
        this._reels = this.allReels.slice(15 - 5, 15);
        let r = []
        if (Array.isArray(this._reels)) { r = this._reels }
        // 添加行数
        for (let reel of r/*this._reels*/) {
            if (reel._nCount != 6) {
                reel.AddCount(6 - reel._nCount, 0.001);
            }
        }
        this.node.scale = 1;
    },

    /**
     * 单列停止
     * colIdx:0开始
     * 回弹动作执行之前的停止时机
     * @override
     * @param colIdx
     * @constructor
     */
    OnReelSpinEnd: function (colIdx) {
        SlotsFacade.bonusGame.reelSpinEnd(colIdx);
    },

    /**
     * 重置所有symbol
     */
    resetAllSymbol() {
        let r = []
        if (Array.isArray(this._reels)) { r = this._reels }
        for (let reel of r/*this._reels*/) {
            for (let s of reel._symbols) {
                s.StartMove();
            }
        }
    }
});