/**
 * 转盘中中的belle bonus
 */
cc.Class({
    extends: cc.Component,

    properties:{
        panel:cc.Node,
        reel1_mask:cc.Node,
        border_top:cc.Node,
        border_bottom:cc.Node,
        border_top:cc.Node,
        spine_bonus:sp.Skeleton,    // 第一列人物动画
        spine_kuang:sp.Skeleton,    // reel 框特效
        spine_reel1_kuang:sp.Skeleton,// reel 第一行 框特效
        spine_fire:sp.Skeleton,     // 火花 特效
        spine_collect_coin:sp.Skeleton,// 结算收集金币 特效
        spine_top:sp.Skeleton,      // 顶部边框动画
        spine_border:sp.Skeleton,   // 背景边框动画
        spineBottom:sp.Skeleton,    // 加金币时底部文本特效
        spine_bonus_pre:sp.Skeleton,// 触发普通bonus前奏动画
        _bottomLabel:cc.Node,      // 公共组件的 金币文本
        _isEnter:false,            // 是否进入bonus游戏
        _isNormal:false,           // 是否是普通模式 true:普通模式 false:免费模式
    },

    onLoad() {
    },

    start() {
        this._bottomLabel = cc.find("winBg/lbl_winNum_nor", SlotsFacade.bottomCmp.node);
        let bottomPos = this._bottomLabel.convertToWorldSpaceAR(cc.v2(0,0));
        bottomPos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(bottomPos);
        this.spineBottom.node.position = bottomPos;
        this.spine_collect_coin.node.parent = SlotsFacade.mainPanel.top_node;
    },

    /**
     * 进入游戏
     */
    enter(isNormal) {
        isNormal = isNormal || false;
        this._isNormal = isNormal;
        this._isEnter = true;
        if(isNormal) {
            //
        }else {
            this.showBorder();
            this.to3RowState(false);
        }
    },

    /**
     * 退出游戏
     */
    exit() {
        this._isEnter = false;
        if(this._isNormal) {

        }else {
            SlotsFacade.dm.triggerBelleBonusCoin = 0;
            this.hideBorder();
        }
    },

    /**
     * 切换到免费 调整panel 和 reel1_mask高度
     */
    toWheelFreeState() {
        this.panel.height = 620;
        this.reel1_mask.height = 600;
    },

    /**
     * 切换到普通 调整panel 和 reel1_mask高度
     */
    toNormalState() {
        this.panel.height = 382;
        this.reel1_mask.height = 362;
    },

    /**
     * 切换到3行模式
     * @param isAni
     */
    async to3RowState(isAni, height) {
        height = height || 430;
        if(isAni) {
            this._hideSpineBonus();
            SlotsFacade.soundMgr.playEffect("bonus_end");
            cc.tween(this.panel)
                .to(0.9, {height:height})
                .call(()=>{
                    SlotsFacade.character.actionSeat();
                })
                .start();
            await SlotsFacade.delayTime(0.9);
        }else {
            this.panel.height = height;
        }
    },

    /**
     * 切换到5行模式
     * @param isAni
     */
    to6RowState(isAni, height) {
        height = height || 740;
        if(isAni) {
            cc.tween(this.panel)
                .call(()=>{
                    // 角色消失
                    SlotsFacade.character.actionDisappear();
                    // 显示第一列角色动画
                    this._showSpineBonus();

                })
                .delay(2)
                .call(()=>{
                    // 显示顶部框动画
                    this.spine_top.node.active = true;
                    this.spine_top.setAnimation(0, "animation", false);
                })
                .delay(0.6)
                // .call(()=>{
                // })
                // .delay(0.5)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("reel_up");
                    this.spine_fire.node.active = true;
                    this.spine_fire.setAnimation(0, "animation", true);
                    this.spine_border.node.active = true;
                    this.spine_border.setAnimation(0, "animation", true);
                })
                .to(1.5, {height:height})
                .call(()=>{
                    this.spine_fire.node.active = false;
                    this.spine_top.node.active = false;
                    this.spine_border.node.active = false;
                    this.showReelBorder(10);
                })
                .start();
        }else {
            this.panel.height = height;
        }
    },

    /**
     * 显示边框
     */
    showBorder() {
        this.border_bottom.active = true;
        this.border_top.active = true;
        this.spine_reel1_kuang.node.active = true;
    },

    /**
     * 隐藏边框
     */
    hideBorder() {
        this.border_bottom.active = false;
        this.border_top.active = false;
        this.spine_reel1_kuang.node.active = false;
        this.spine_bonus.node.active = false;
    },

    /**
     * 显示reel框
     * @param idx
     */
    showReelBorder(idx) {
        let row = 6;
        if(this._isNormal) {
            row = 3;
        }
        if(idx >= 10 && idx<=13) {
            let aniName = `animation${row}_${14-idx}`;
            this.spine_kuang.node.active = true;
            this.spine_kuang.setAnimation(0, aniName, true);
        }else {
            this.spine_kuang.node.active = false;
        }
        if(idx>=10 && idx<14) {
            SlotsFacade.soundMgr.playEffect(`bonus_active${idx%10 + 1}`);
        }
        if(idx>10 && idx <=14) {
            SlotsFacade.soundMgr.playEffect(`coin_land${idx%10}`);
        }

        // 设置symbol的bonus状态
        if(idx == 10) {
            let reels = SlotsFacade.slots._reels;
            for(let r of reels) {
                for(let s of r._symbols) {
                    s.setBonusState(true);
                }
            }
        }
    },

    /**
     * 开始停止游戏
     */
    reelSpinEnd(colIdx) {
        if(!this._isEnter) {
            return;
        }
        if(colIdx == 10) {
            if(this._isNormal) {
                cc.tween(this.panel)
                    .call(()=>{
                        // 点亮边框
                        this.spine_border.node.active = true;
                        this.spine_border.setAnimation(0, "animation", true);
                        // 显示第一列角色动画
                        this._showSpineBonus();
                        // 角色消失
                        SlotsFacade.character.actionDisappear();
                    })
                    .delay(2)
                    .call(()=>{
                        this.spine_border.node.active = false;
                        this.showReelBorder(10);
                    })
                    .start();
            }else {
                if(SlotsFacade.dm.getBonusInfo()) {
                    this.to6RowState(true);
                }
            }
        }else {
            if(this._isNormal || SlotsFacade.dm.getBonusInfo()) {
                this.showReelBorder(colIdx);
            }
        }
    },

    /**
     * 显示第一列任务动画
     * @private
     */
    _showSpineBonus() {
        SlotsFacade.soundMgr.playEffect("bonus_land");
        this.spine_bonus.node.active = true;
        this.spine_bonus.node.opacity = 0xff;
        this.spine_bonus.setAnimation(0, "animation1", false);
        this.spine_bonus.addAnimation(0, "animation2", true);
    },

    /**
     * 隐藏第一列任务动画
     * @private
     */
    _hideSpineBonus() {
        if(!this.spine_bonus.node.active) {
            return;
        }
        this.spine_bonus.setAnimation(0, "animation5", false);
        cc.tween(this.spine_bonus.node)
            .delay(0.7)
            .to(0.2, {opacity:0})
            .call(()=>{
                this.spine_bonus.node.active = false;
            })
            .start();
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async startMove() {
        if(this._isEnter) {
            await this.to3RowState(true);
        }else {
            if(this.spine_bonus.node.active) {
                this._hideSpineBonus();
                SlotsFacade.character.actionSeat();
            }
        }
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        if(!this._isEnter) {
            return;
        }
        if(this._isNormal) {
            SlotsFacade.soundMgr.playEffect("active_woman");
            SlotsFacade.character.actionShine();
            this.spine_bonus_pre.node.active = true;
            this.spine_bonus_pre.setAnimation(0, "animation2", false);
            await new Promise(res=>{
                this.spine_bonus_pre.setCompleteListener(()=>{
                    this.spine_bonus_pre.setCompleteListener(null);
                    this.spine_bonus_pre.node.active = false;
                    res();
                });
            })
            await SlotsFacade.delayTime(0.5);
        }else {
            await SlotsFacade.delayTime(1);
        }
    },

    /**
     * 旋转停止
     * @returns {Promise<void>}
     */
    async spinEnd() {
        if(!this._isEnter) {
            return;
        }
        if(this._isNormal){
            await this.extendBonus();
            await this.settlement();
            this.exit();
        }else if(SlotsFacade.dm.getBonusInfo()) {
            await this.extendBonus();
            await this.settlement();
        }
    },

    /**
     * 扩展bonus
     */
    async extendBonus() {
        let bonusInfo = SlotsFacade.dm.getBonusInfo();
        let aniName = "";
        if(this._isNormal) {
            aniName = "animation3";
        }else {
            aniName = "animation4";
        }
        this.spine_bonus.setAnimation(0, aniName, false);
        this.spine_bonus.addAnimation(0, "animation2", true);
        let extraItems = bonusInfo.extraItems;
        let extraColArr = [[], [], [], [], []];
        for(let i of extraItems) {
            let col = (i.idx-1)%5;
            extraColArr[col].push(i);
        }
        // for(let i=0; i<extraColArr.length; i++) {
        //     if(extraColArr[i].length < 1) {
        //         extraColArr.splice(i, 1);
        //         i--;
        //     }
        // }
        for(let i=0; i<extraColArr.length;i++) {
            let colArr = extraColArr[i];
            for(let item of colArr) {
                let symbol = SlotsFacade.slots.GetSymbolByIdx(item.idx);
                symbol.changeToBonusSymbol(item.coin);
            }
            if(colArr.length>0) {
                SlotsFacade.soundMgr.playEffect("bonus_fire");
            }
            await SlotsFacade.delayTime(0.2);
        }
        await SlotsFacade.delayTime(0.5);
        // 播放trigger动画
        let allBonusItem = bonusInfo.items.concat(bonusInfo.extraItems);
        for(let item of allBonusItem) {
            let symbol = SlotsFacade.slots.GetSymbolByIdx(item.idx);
            symbol.playTriggerAnimation();
        }
        await SlotsFacade.delayTime(0.6);
    },

    /**
     * 结算金币
     */
    async settlement() {
        let bonusInfo = SlotsFacade.dm.getBonusInfo();
        let allBonusItem = bonusInfo.items.concat(bonusInfo.extraItems);
        allBonusItem.sort((a, b)=>{
            let colA = (a.idx-1)%5;
            let colB = (b.idx-1)%5;
            if(colA-colB == 0) {
                return a.idx - b.idx;
            }else {
                return colA - colB;
            }
        })
        this.spine_collect_coin.node.active = true;
        this._bottomLabel.active = true;
        let startCoin = 0;
        let sum = 0;
        if(!this._isNormal){
            startCoin = cc.vv.gameData.GetGameTotalFreeWin();
            sum = startCoin - bonusInfo.winCoin;
        }
        this.spineBottom.node.position = this.spineBottom.node.parent.convertToNodeSpaceAR(cc.vv.gameData.GetBottomScript().getWinLabelNor().convertToWorldSpaceAR(cc.v2(0,0)));
        for(let item of allBonusItem) {
            SlotsFacade.soundMgr.playEffect("coin_collect");
            let symbol = SlotsFacade.slots.GetSymbolByIdx(item.idx);
            symbol.playBonusLight();
            let val = item.coin;
            let pos = SlotsFacade.slots.getIdxGlobalPos(item.idx);
            pos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(pos);
            let aniName = `animation${(item.idx-1)%5}_${Math.ceil((item.idx+(this._isNormal?15:0))/5)}`;
            this.spine_collect_coin.node.position = pos;
            this.spine_collect_coin.setAnimation(0, aniName, false);
            await SlotsFacade.delayTime(0.5);
            this.spineBottom.node.active = true;
            this.spineBottom.setAnimation(0, "animation", false);
            // 更新金币
            await new Promise(res=>{
                Global.doRoallNumEff(this._bottomLabel, sum, sum+val, 0.3, res, null,0,true)
            })
            sum += val;
        }
        this.spine_collect_coin.node.active = false;
    },
 })