/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        this.enterNormalGame(true);
        await SlotsFacade.popup.showEnterTheme();
        await SlotsFacade.character.actionSeat(true);
        if(SlotsFacade.dm.energyData.state > 0) {
            await this.enterCollectGame(true);
        }
        if(SlotsFacade.dm.wheelGame) {
            await this.enterWheelGame(true);
        }
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal);
            await this.enterFreeGame(true);
        }
        if(SlotsFacade.dm.energyData.state != 1) {
            // todo recover
            SlotsFacade.slots.CanDoNextRound();
        }
    },

    /**
     * 开始移动
     */
    async startMove() {
        SlotsFacade.wildGame.startMove();
        SlotsFacade.bonusGame.startMove();
    },

    /**
     * 收到spin消息
     * @param {*} msg
     */
    async onSpinMsg(msg) {
        await SlotsFacade.wildGame.onSpinMsg();
        if(SlotsFacade.dm.isTriggerNormalBonus()) {
            SlotsFacade.bonusGame.enter(true);
        }
        await SlotsFacade.bonusGame.onSpinMsg();
        await SlotsFacade.freeGame.onSpinMsg();
        SlotsFacade.slots._gameInfo = msg;
        let cards = msg.resultCards;
        if(SlotsFacade.dm.mapFreeInfo) {
            cards = SlotsFacade.dm.mapFreeInfo.cards;
        }
        SlotsFacade.slots.SetSlotsResult(cards);
        SlotsFacade.slots.SetReelStateInfo(cards);
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        // 收集能量
        await this.collectEnergy();
        await SlotsFacade.wildGame.spinEnd();
        await SlotsFacade.bonusGame.spinEnd();
        await SlotsFacade.freeGame.spinEnd();
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
        await this.collectBag();
        // await SlotsFacade.delayTime(0.5);
        // 进入收集游戏
        await this.enterCollectGame();
        // 进入wheel game
        await this.enterWheelGame();
        // 控制按钮
        if (SlotsFacade.dm.isFistTriggerFree()) {
            await this.enterFreeGame();
        } else if (SlotsFacade.dm.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.stopBgm();
            if(SlotsFacade.dm.energyData.state == 2) {
                await SlotsFacade.popup.showWinMapFreeGold(SlotsFacade.dm.getFreeWinCoin());
                await SlotsFacade.mainPanel.showSceneTransition(3);
            }else {
                await SlotsFacade.popup.showWinWheelFreeGold(SlotsFacade.dm.getFreeWinCoin(), SlotsFacade.dm.belleBonus?true:false);
                await SlotsFacade.mainPanel.showSceneTransition(1);
            }
            SlotsFacade.slots.resetAllSymbol();
            SlotsFacade.slots.Resume();
            await this.enterNormalGame();
        }
        if(SlotsFacade.dm.energyData.state != 1) {
            // todo recover
            SlotsFacade.slots.CanDoNextRound();
        }
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame(isReconnect) {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        let freeType = 1;
        let mapInfo = SlotsFacade.dm.energyData;
        let mapItem = SlotsFacade.dm.getGameCfg().mapCfg[mapInfo.currId + ""];
        if(mapInfo.state == 2) {
            freeType = mapItem.type;
        }
        if(!isReconnect) {
            if(freeType == 1) {
                SlotsFacade.slots.Backup();
            }
        }
        SlotsFacade.mainPanel.showBg(2);
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = freeType == 1;
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total);
        if(mapInfo.state == 2) {
            SlotsFacade.slots.toMapFreeState();
            await SlotsFacade.wildGame.enterWildGame();
            SlotsFacade.soundMgr.playBgm("map_bgm");
        }else {
            if(SlotsFacade.dm.belleBonus) {
                SlotsFacade.slots.toWheelBonusState();
                SlotsFacade.bonusGame.enter();
            }else {
                SlotsFacade.slots.toWheelFreeState();
                SlotsFacade.freeGame.enter();
                SlotsFacade.soundMgr.playBgm("free_bgm");
            }
        }
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 进入普通游戏
     */
    async enterNormalGame(reconnect) {
        reconnect = reconnect || false;
        SlotsFacade.collectProgress.setEnterEnable(true);
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.slots.toNormalState();
        if(!reconnect) {
            SlotsFacade.soundMgr.playBgm(null, true);
        }
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = true;
        SlotsFacade.wildGame.exitWildGame();
        SlotsFacade.bonusGame.exit();
        SlotsFacade.freeGame.exit();
        if(SlotsFacade.dm.isLastEndFree()) {
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal, nTotal,true, res);
            });
        }
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        let progressData = SlotsFacade.dm.energyData.progressData;
        if (progressData && progressData.currCnt) {
            let items = SlotsFacade.slots.getSymbolsByServerIds(SlotsFacade.dm.getCollectSymbolIndexs());
            let posArr = [];
            items.forEach(v => {
                posArr.push(v.node.convertToWorldSpaceAR(cc.v2(0, 0)));
            });
            if(SlotsFacade.dm.getCollectPercent() >= 1){
                await SlotsFacade.collectProgress.collectEnergy(posArr, SlotsFacade.dm.getCollectPercent());
            }else {
                SlotsFacade.collectProgress.collectEnergy(posArr, SlotsFacade.dm.getCollectPercent());
            }
        }
    },

    /**
     * 搜集钱袋
     * @returns {Promise<void>}
     */
    async collectBag() {
        await SlotsFacade.bagGame.collectEnergy();
    },

    /**
     * 进入地图游戏
     * @param reconnect
     * @returns {Promise<void>}
     */
    async enterCollectGame(reconnect) {
        let energyData = SlotsFacade.dm.energyData;
        if (energyData.state > 0) {
            let canEnter = false;
            if(reconnect) {
                if(energyData.state == 1) {// 如果是重连进来只有777游戏才能进入地图
                    canEnter = true;
                }
            }else {
                if(energyData.state == 2 && SlotsFacade.dm.isFistTriggerFree()) {
                    canEnter = true;
                }
                if(energyData.state == 1) {
                    canEnter = true;
                }
            }
            if(canEnter) {
                Global.SlotsSoundMgr.stopBgm();
                SlotsFacade.topCmp.SetBackLobby(false);
                SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1")  ;
                if(!reconnect) {
                    await SlotsFacade.collectProgress.playCollectComplete();
                }
                await new Promise(res => {
                    SlotsFacade.map.enterMap(false, res);
                });
            }
        }
    },

    /**
     * 进入whee game游戏
     * @returns {Promise<void>}
     */
    async enterWheelGame(isReconnect) {
        if(SlotsFacade.dm.wheelGame) {
            let ret = await new Promise(res=>{
                SlotsFacade.wheelGame.open(res, isReconnect);
            })
            if(ret.type == 3) {
                await SlotsFacade.popup.showWinWheelBag(ret.coin);
            }
            let winCoin = ret.coin;
            if(winCoin > 0) {
                let totalCoin = winCoin;
                if(SlotsFacade.dm.getSpinData()) {
                    totalCoin += SlotsFacade.dm.GetGameWin();
                }
                SlotsFacade.dm.AddCoin(winCoin);
                await new Promise(res=>{
                    SlotsFacade.slots.ShowBottomWin(winCoin, totalCoin,true, res);
                });
            }
        }
    },
 })