
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        head:cc.Node,               // 收集条头部节点
        tail:cc.Node,               // 收集条尾部节点
        progressBar: cc.Node,       // 进度条节点
        spine_collect_lock:sp.Skeleton, // 能量条状态spine动画
        spine_full:sp.Skeleton,     // 集满播放spine动画
        tips:cc.Node,               // 进度条说明提示
        item_template:cc.Node,      // 收集symbol模板

        _isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._initListener();
    },

    start() {
        this.scheduleOnce(()=>{
            this._init();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.tail.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            this._showTips();
            if(!this._isOpen) {
                this._openCollect();
            }
        }, this);
    },

    /**
     * 显示收集 说明提示
     */
    _showTips() {
        if(this.tips.active) {
            return;
        }
        this.tips.active = true;
        this.tips.opacity = 0;
        cc.tween(this.tips)
            .to(0.5, { opacity: 0xff })
            .delay(2)
            .to(0.5, {opacity:0})
            .call(()=>{
                this.tips.active = false;
            })
            .start();
    },

    _init() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.showCollect(true);
        this._updateEnterBtnIcon();
    },

    /**
     * 点击按钮进入地图
     * @private
     */
    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        // 自动旋转模式 返回
        if(SlotsFacade.dm.GetAutoModelTime() > 0) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("click");
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.map.enterMap(true, ()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        SlotsFacade.soundMgr.playEffect("collect_fly");
        let endPos = this.head.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let item = cc.instantiate(this.item_template);
            item.parent = this.node;
            item.position = pos;
            item.active = true;
            promiseArr.push(new Promise(res=>{
                cc.tween(item)
                    .to(0.2, {scale:1.3})
                    .to(0.4, {x:endPos.x, y:endPos.y, scale:0.6})
                    .call(()=> {
                        item.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        await Promise.all(promiseArr);
        this._playHeadSpine();
        this.setProgress(percent, true);
    },

    /**
     * 头部动画
     */
    _playHeadSpine() {
        // let spineIcon = this.head.getChildByName("spine_icon").getComponent(sp.Skeleton);
        // spineIcon.setAnimation(0, "animation2", false);
        // spineIcon.addAnimation(0, "animation1", true);

        let spineEff = this.head.getChildByName("spine_effect").getComponent(sp.Skeleton);
        spineEff.node.active = true;
        spineEff.setAnimation(0, "animation", false);
        spineEff.setCompleteListener(()=>{
            spineEff.setCompleteListener(null);
            spineEff.node.active = false;
        });
    },

    /**
     * 显示收集界面
     * @param isInit 是否是初始化
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(isInit) {
                this.spine_collect_lock.node.active = false;
            }else {
                if(!this._isOpen) {
                    this.spine_collect_lock.node.active = true;
                    SlotsFacade.soundMgr.playEffect("collect_unlock");
                    this.spine_collect_lock.setAnimation(0, "animation2", false);
                    this._showTips();
                }
            }
        }else {
            if(isInit) {
                this.spine_collect_lock.node.active = true;
                this.spine_collect_lock.setAnimation(0, "animation3", false);
            }else {
                if(this._isOpen) {
                    this.spine_collect_lock.node.active = true;
                    SlotsFacade.soundMgr.playEffect("collect_lock");
                    this.spine_collect_lock.setAnimation(0, "animation1", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 播放收集完成动画
     */
    async playCollectComplete() {
        SlotsFacade.soundMgr.playEffect("collect_full");
        this.spine_full.node.active = true;
        this.spine_full.setAnimation(0, "animation", false);
        await new Promise(res=>{
            this.spine_full.setCompleteListener(()=>{
                this.spine_full.setCompleteListener(null);
                this.spine_full.node.active = false;
                res();
            })
        })
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        let w = this.progressBar.width;
        let toX = -w + percent * w;
        let bar = this.progressBar.getChildByName("bar");
        if(needTransform) {
            let colectEffect = bar.getChildByName("effect").getComponent(sp.Skeleton);
            colectEffect.node.active = true
            colectEffect.setAnimation(0, "animation", false);
            colectEffect.getComponent(sp.Skeleton).setCompleteListener(()=>{
                colectEffect.active = false
                colectEffect.getComponent(sp.Skeleton).setCompleteListener(null)
            });
            cc.tween(bar).to(0.5, {x:toX}).start();
        }else {
            bar.x = toX;
            if(percent == 0) {
                this._updateEnterBtnIcon();
            }
        }
    },

    setEnterEnable(boo) {
        // todo
    },

    /**
     * 更新进入地图按钮图标
     * @private
     */
    _updateEnterBtnIcon() {
        let energyData = SlotsFacade.dm.energyData;
        if(!energyData) {
            return;
        }
        let currId = energyData.currId;
        if(currId < 1) {
            currId = 1;
        }
        let mapItemCfg = SlotsFacade.dm.getGameCfg().mapCfg[currId.toString()];
        let spine = this.tail.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, mapItemCfg.iconAni, true);
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    }
});
