let CoinAniCfg = {
    "1":{idleAni:"animation1", staticAni:"animation1", dynamicAni:"animation6"},
    "2":{idleAni:"animation2", staticAni:"animation2", dynamicAni:"animation4"},
    "3":{idleAni:"animation3", staticAni:"animation3", dynamicAni:"animation5"},
}
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node,
        spine_coin:sp.Skeleton,
        spine_idle:sp.Skeleton,
        spine_win:sp.Skeleton,
        spine_collect_end:sp.Skeleton,
        collect_item_template:cc.Node,
        win_dialog:cc.Node,
        spineBottom:sp.Skeleton,    // 加金币时底部文本特效
    },

    onLoad() {
    },

    start() {
        this._bottomLabel = cc.find("winBg/lbl_winNum_nor", SlotsFacade.bottomCmp.node);
        let bottomPos = this._bottomLabel.convertToWorldSpaceAR(cc.v2(0,0));
        bottomPos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(bottomPos);
        this.spineBottom.node.position = bottomPos;
        this._setStep(this._getBelleBagLevel(), false);
    },

    async _setStep(step, ani) {
        step = step || 1;
        let aniCfg = CoinAniCfg[step.toString()];
        this.spine_idle.setAnimation(0, aniCfg.idleAni, true);
        this.spine_coin.node.active = true;
        if(ani) {
            if(this.spine_coin.animation != aniCfg.staticAni) {
                SlotsFacade.soundMgr.playEffect("bag_up");
                this.spine_coin.setAnimation(0, aniCfg.dynamicAni, false);
                this.spine_coin.addAnimation(0, aniCfg.staticAni, false);
                await new Promise(res=>{
                    this.spine_coin.setCompleteListener(()=>{
                        this.spine_coin.setCompleteListener(null);
                        res();
                    })
                })
            }
        }else {
            this.spine_coin.setAnimation(0, aniCfg.staticAni, false);
        }
    },

    /**
     * 收集钱袋
     */
    async collectEnergy() {
        let belleBag = SlotsFacade.dm.belleBag;
        if(!belleBag.wildCols || belleBag.wildCols.length<1) {
            return;
        }
        SlotsFacade.slots.resetAllSymbol();
        // 收集逻辑
        SlotsFacade.soundMgr.playEffect("bag_collect");
        let topNode = SlotsFacade.mainPanel.top_node;
        let endPos = this.node.convertToWorldSpaceAR(cc.v2(0,0));
        endPos = topNode.convertToNodeSpaceAR(endPos);
        for(let i=0; i<belleBag.wildCols.length; i++) {
            let idx = belleBag.wildCols[i];
            let startPos = SlotsFacade.slots.getIdxGlobalPos(idx+5);
            startPos = topNode.convertToNodeSpaceAR(startPos);
            let spine = cc.instantiate(this.collect_item_template).getComponent(sp.Skeleton);
            spine.node.parent = topNode;
            spine.node.position = startPos;
            spine.node.active = true;
            spine.setAnimation(0, "animation", false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                spine.node.removeFromParent(true);
            })
            cc.tween(spine.node)
                .delay(0.6)
                .to(0.6, {x:endPos.x, y:endPos.y})
                .call(()=> {
                    this.spine_collect_end.node.active = true;
                    this.spine_collect_end.setAnimation(0, "animation", false);
                })
                .start();
        }
        await SlotsFacade.delayTime(1.6);
        this.spine_collect_end.node.active = false;
        await this._setStep(this._getBelleBagLevel(), true);
        await this._collectCoin();
    },

    /**
     * 获取当前收集所处等级
     * @private
     */
    _getBelleBagLevel() {
        let belleBag = SlotsFacade.dm.belleBag;
        let percent = belleBag.totalCnt/belleBag.maxCnt;
        if(percent<0.1) {
            return 1;
        }else if(percent<0.5) {
            return 2;
        }else {
            return 3;
        }
    },

    /**
     * 收集金币
     * @private
     */
    async _collectCoin() {
        let belleBag = SlotsFacade.dm.belleBag;
        if(belleBag.totalCnt < belleBag.maxCnt) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("bag_roll");
        this.spine_win.node.active = true;
        this.win_dialog.active = true;
        // 显示文本
        let bg = this.win_dialog.getChildByName("bg");
        bg.active = true;
        let label = this.win_dialog.getChildByName("label").getComponent("LabelRollCmp");
        label.node.active = true;
        label.node.scale = 0.3;
        label.node.opacity = 150;
        label.startRoll(0, belleBag.totalCoin, 3);
        cc.tween(label.node)
            .to(3, {scale:1.2, opacity:0xff})
            .to(0.3, {scale:1}, {easing:"backIn"})
            .start();
        await SlotsFacade.delayTime(3);
        this.spine_win.node.active = false;
        let spine = this.win_dialog.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation1", false);
        spine.addAnimation(0, "animation2", true);
        await SlotsFacade.delayTime(2);
        // 关闭弹窗
        spine.setAnimation(0, "animation3", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
            this.win_dialog.active = false;
        });
        label.node.active =false;
        // 移动 文本到底部
        SlotsFacade.soundMgr.playEffect("bag_footer");
        let labelCopy = cc.instantiate(label.node);
        labelCopy.active = true;
        labelCopy.parent = SlotsFacade.mainPanel.top_node;
        let startPos = label.node.convertToWorldSpaceAR(cc.v2(0,0));
        startPos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(startPos);
        labelCopy.position = startPos;
        let endPos = this.spineBottom.node.position;
        cc.tween(labelCopy)
            .to(1, {scale:0.3, x:endPos.x, y:endPos.y}, {easing:"backIn"})
            .call(()=>{
                this.spineBottom.node.active = true;
                this.spineBottom.setAnimation(0, "animation", false);
                labelCopy.removeFromParent(true);
            })
            .start();

        let startCoin = SlotsFacade.dm.GetGameWin() - belleBag.totalCoin;
        await new Promise(res=>{
            Global.doRoallNumEff(this._bottomLabel, startCoin, startCoin+belleBag.totalCoin, 0.3, res, null,0,true)
        })
        this._setStep(1, true);
    },

    show(){
        this.bg.active = true;
        this.node.active = true;
    },

    hide() {
        this.bg.active = false;
        this.node.active = false;
    }

 })