/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        energyData: null,     // 能量数据
        mapFreeInfo: null,     // 处理后的地图数据
        wheelGame: null,     // 转盘数据
        belleBonus: null,     // free bonus数据
        triggerBelleBonusCoin: 0, // 触发belleBonus时的金币
        belleBag: null,     // 钱袋信息
    },

    init(deskInfo, gameId, gameJackpot) {
        this._super(deskInfo, gameId, gameJackpot);
        this.energyData = this._deskInfo.mapInfo;
        this.wheelGame = this._deskInfo.wheelGame;
        this.belleBonus = this._deskInfo.belleBonus;
        if (this.belleBonus) {
            this.SetTotalFree(5);
            this.SetFreeTime(this.belleBonus.restCnt);
        }
        this.belleBag = this._deskInfo.belleBag;
    },

    //注册msg
    RegisterMsg() {
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg() {
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine: function (msg) {
        if (msg.code == 200) {
            this.energyData = msg.mapInfo;
            this.mapFreeInfo = this._processMapFreeData(msg.freeGameSlots);
            this.wheelGame = msg.wheelGame;
            this.belleBonus = msg.belleBonus;
            if (!this.belleBonus) {
                this._processBonusInfo(msg);
            }
            if (msg.belleBag) {
                this.belleBag = msg.belleBag;
            } else {
                if (this.belleBag) {
                    this.belleBag.wildCols = null;
                }
            }
        }
        this._super(msg);
    },

    SetSubGameData: function (data) {
        this._subGame = data;
    },

    GetSubGameData: function () {
        return this._subGame;
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this._gameInfo.freeResult;
        if (freeResult && freeResult.triFreeCnt && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
            return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if (this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    ///////////////////////////收集相关/////////////////
    /**
     * 获取当前收集进度
    */
    getCollectPercent() {
        if (!this.energyData || !this.energyData.progressData) {
            return 0;
        }
        let percent = this.energyData.progressData.totalCnt / this.energyData.progressData.needCnt;
        percent = Math.min(1, percent);
        percent = Math.max(0, percent);
        return percent;
    },

    /**
     * 获取结果中收集图标得的下标
     */
    getCollectSymbolIndexs() {
        let cards = this._gameInfo.resultCards
        if (!cards || cards.length < 1) {
            return [];
        }
        let ret = [];
        cards.forEach((v, i) => {
            if (this.getGameCfg().isEnergyId(v)) {
                ret.push(i + 1);
            }
        });
        return ret;
    },

    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c: MsgId.SLOT_SUBGAME_DATA,
            gameid: this._gameId,
            data: param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg) {
        console.log("<<<< reqSubGame-resp: ", msg);
        if (msg.data.rtype === 2) {
            SlotsFacade.wheelGame.onMsg(msg);
        } else if (msg.data.rtype == 3) {
            this._onBonusMsg(msg.data);
        }
    },

    ///////////////////////////数据转换相关/////////////////
    /**
     * 处理地图免费游戏数据
     * @param freeGameSlots
     * @returns {null|{randomWilds: null, cards: *[], zjLuXian: *[]}}
     * @private
     */
    _processMapFreeData(freeGameSlots) {
        if (!freeGameSlots) {
            return null;
        }
        let ret = {
            cards: [],           // 牌值
            zjLuXian: [],        // 中奖路线
            randomWilds: [],     // 随机wild idxs
            multWilds: [],       // 倍数
            moveWilds: {         // 移动wild
                currIdxs: [],    // 本局结束后wild 的idx
                randIdxs: [],    // 移动后wild的idx
            },
            stickyWilds: [],     // 固定wild
        }
        for (let i = 0; i < freeGameSlots.length; i++) {
            let item = freeGameSlots[i];
            // symbol
            ret.cards = ret.cards.concat(item.cards);
            // zjLuXian
            let zjLuXian = item.zjLuXian;
            zjLuXian = (Array.isArray(zjLuXian)) ? zjLuXian : (zjLuXian && typeof zjLuXian === "object") ? Object.values(zjLuXian) : [] // By JerryWong
            for (let lx of zjLuXian) {
                this.convertIdx(i, lx.indexs);
            }
            ret.zjLuXian = ret.zjLuXian.concat(zjLuXian);
            // randomWilds
            if (item.randomWilds) {
                this.convertIdx(i, item.randomWilds.currIdxs);
                ret.randomWilds = ret.randomWilds.concat(item.randomWilds.currIdxs);
            }
            // wildMults
            if (item.multWilds) {
                ret.multWilds.push(item.multWilds.wildMult);
            }
            // moveWilds
            if (item.moveWilds) {
                this.convertIdx(i, item.moveWilds.currIdxs);
                this.convertIdx(i, item.moveWilds.randIdxs);
                ret.moveWilds.currIdxs = ret.moveWilds.currIdxs.concat(item.moveWilds.currIdxs);
                ret.moveWilds.randIdxs = ret.moveWilds.randIdxs.concat(item.moveWilds.randIdxs);
            }
            // stickyWilds
            if (item.stickyWilds) {
                this.convertIdx(i, item.stickyWilds.currIdxs);
                ret.stickyWilds = ret.stickyWilds.concat(item.stickyWilds.currIdxs);
            }
        }
        return ret;
    },
    /**
     * 转换下标
     * @param slotsIdx
     * @param cards
     */
    convertIdx(slotsIdx, cards) {
        for (let i = 0; i < cards.length; i++) {
            cards[i] = slotsIdx * 15 + cards[i];
        }
    },

    /**
     * 获取中奖路线相关数据
     * @returns {*}
     */
    getZjLuXian() {
        if (this.mapFreeInfo) {
            return this.mapFreeInfo.zjLuXian;
        } else {
            return this._gameInfo.zjLuXian;
        }
    },

    ///////////////////////////belle bonus 相关/////////////////
    _onBonusMsg(bonusMsg) {
        // 构造 消息
        let msg = {
            "gameid": 511,
            "c": 44,
            "code": 200,
            "lastBetCoin": 0,
            "wincoin": 0,
            "freeCnt": 0,
            "mults": null,
            "coin": 0,
            "allFreeCnt": 5,
            "betcoin": 0,
            "mapInfo": null,
            "freeWinCoin": 0,
            "zjLuXian": null,
            "freeResult": {
                "triFreeCnt": 1,
                "freeInfo": []
            },
            "resultCards": [],
            "bonusInfo": {
                "items": [],
                "winCoin": 0,
                "isTrigger": false,
                "extraItems": []
            },
            "belleBonus": null,
        };
        let cards = [
            20, 20, 20, 20, 20,
            20, 20, 20, 20, 20,
            20, 20, 20, 20, 20,
            301, 20, 20, 20, 20,
            301, 20, 20, 20, 20,
            301, 20, 20, 20, 20
        ];
        let zjLuXian = [];
        let cfg = this.getGameCfg();
        let bonusInfo = bonusMsg.belleBonus.bonusInfo;
        let slotInfo = bonusMsg.belleBonus.slotInfo;
        if (bonusInfo) {
            for (let i of bonusInfo.items) {
                let newIdx = i.idx + Math.ceil(i.idx / bonusInfo.col);
                cards[newIdx - 1] = cfg.bonusId;
                i.idx = newIdx;
            }
            for (let i of bonusInfo.extraItems) {
                let newIdx = i.idx + Math.ceil(i.idx / bonusInfo.col);
                i.idx = newIdx;
            }
        } else if (slotInfo) {
            zjLuXian = slotInfo.zjLuXian;
            for (let lx of zjLuXian) {
                for (let i = 0; i < lx.indexs.length; i++) {
                    lx.indexs[i] += 15;
                }
            }
            for (let i = 0; i < slotInfo.cards.length; i++) {
                cards[15 + i] = slotInfo.cards[i];
            }
        }
        msg.coin = this.GetCoin();
        msg.freeWinCoin = bonusMsg.belleBonus.winCoin;
        msg.freeWinCoin += this.triggerBelleBonusCoin;
        if (bonusMsg.belleBonus.bonusInfo) {
            // msg.wincoin = bonusMsg.belleBonus.bonusInfo.winCoin;
            msg.wincoin = 0;
        } else if (bonusMsg.belleBonus.slotInfo) {
            msg.wincoin = bonusMsg.belleBonus.slotInfo.winCoin;
        }
        msg.allFreeCnt = 5;
        msg.freeCnt = bonusMsg.belleBonus.restCnt;
        msg.mapInfo = this.energyData;
        msg.mults = this._deskInfo.mults;
        msg.belleBonus = bonusMsg.belleBonus;
        msg.resultCards = cards;
        msg.zjLuXian = zjLuXian;
        this.OnRcvNetSpine(msg);
    },

    /**
     * 处理普通游戏中的bonus info
     * @param bonusInfo
     * @private
     */
    _processBonusInfo(msg) {
        let bonusInfo = msg.bonusInfo;
        if (!bonusInfo || !bonusInfo.isTrigger) {
            return;
        }
        // 设置第一列为五角星图标
        msg.resultCards[0] = 301;
        msg.resultCards[5] = 301;
        msg.resultCards[10] = 301;

        let cfg = this.getGameCfg();
        // 设置items 为 bonus 图标
        for (let i of bonusInfo.items) {
            msg.resultCards[i.idx - 1] = cfg.bonusId;
        }
        // 设置 extraItems 为空白图标
        for (let i of bonusInfo.extraItems) {
            msg.resultCards[i.idx - 1] = cfg.blankId;
        }
        // 设置赢取金币
        msg.wincoin = bonusInfo.winCoin;
    },

    getBonusInfo() {
        let ret = null;
        if (this.belleBonus) {
            ret = this.belleBonus.bonusInfo;
        } else {
            if (this.isTriggerNormalBonus()) {
                ret = this.getSpinData().bonusInfo;
            }
        }
        return ret;
    },

    /**
     * 是否出发普通bonus
     */
    isTriggerNormalBonus() {
        return this.getSpinData() && this.getSpinData().bonusInfo && this.getSpinData().bonusInfo.isTrigger;
    }
});
