let WheelItemType = {
    jackpot:1,
    freeGame:2,
    belleBag:3,
    belleBonus:4,
}
let WheelItemConfig = {
    "Grand":{type:WheelItemType.jackpot, iconIndex:0},
    "Major":{type:WheelItemType.jackpot, iconIndex:1},
    "Minor":{type:WheelItemType.jackpot, iconIndex:2},
    "belleBag":{type:WheelItemType.belleBag, iconIndex:3},
    "freeGame":{type:WheelItemType.freeGame, iconIndex:4},
    "belleBonus":{type:WheelItemType.belleBonus, iconIndex:5},
};
let WheelListCfg = [
    "Grand",
    "freeGame",
    "Minor",
    "belleBonus",
    "Major",
    "belleBag",
    "Minor",
    "freeGame",
    "Grand",
    "belleBonus",
    "Minor",
    "belleBag",
    "Major",
    "belleBonus",
    "Minor",
    "belleBag",
    "Major",
    "freeGame",
];
cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        wheel:cc.Node,
        startNode:cc.Node,
        frame:cc.Node,
        items:[cc.Node],
        proxy:cc.Node,  // 用来产生旋转角度数据的节点空节点即可
        spine_border_idle:sp.Skeleton,  // 边框idle动画
        spine_border_start:sp.Skeleton, // 开始时边框动画
        spine_run:sp.Skeleton,  // 转动火光动画
        spine_win:sp.Skeleton,  // 旋转结束选中结果动画

        _cbHandler:null,
        _canMove:false,
        _wheelCfg:null, // 转轴相关配置
        _respData:null,
    },

    onLoad() {
        this._wheelCfg = {
            baseRound:10,                    // 基础旋转圈数
            itemsLen:this.items.length,     // 元素个数
            itemHeight:this.items[0].height,// 单个元素高度
            totalHeight:0,                  // 元素总高度
        }
        this._wheelCfg.totalHeight = this._wheelCfg.itemsLen * this._wheelCfg.itemHeight;
    },

    /**
     * 获取旋转角度
     * @param index
     * @returns {number}
     * @private
     */
    _getRotation(index) {
        let baseRound = this._wheelCfg.baseRound;
        // let itemLen = this.items.length;
        // let unitAngle = 360/itemLen;  // 单个旋转选项对应的旋转角度
        // return baseRound * 360 + index*unitAngle;
        return baseRound * 360;
    },

    /**
     * 开始旋转
     * @private
     */
    async _startWheel() {
        SlotsFacade.soundMgr.playEffect("wheel_roll2");
        let rotation = this._getRotation(0);
        this.proxy.rotation = 0;
        // 火花动画
        cc.tween(this.node)
            .delay(1)
            .call(()=>{
                this.spine_run.node.active = true;
                this.spine_run.setAnimation(0, "animation", true);
            })
            .start();
        // 设置结果
        cc.tween(this.node)
            .delay(3)
            .call(()=>{
                let img = this.items[4].getComponent("ImgSwitchCmp");
                let itemCfg = WheelItemConfig[WheelListCfg[this._respData.result.wheelId-1]];
                img.setIndex(itemCfg.iconIndex);
            })
            .start();
        await new Promise(res=>{
            cc.tween(this.proxy)
                .call(()=> {
                    this._canMove = true;
                    SlotsFacade.soundMgr.playEffect("wheel_spin");
                })
                .to(7.5, {rotation:rotation}, {easing:"quartInOut"})
                .call(()=>{
                    this.spine_run.node.active = false;
                })
                .delay(0.1)
                .call(()=>{
                    // SlotsFacade.soundMgr.playEffect("option");
                    this._canMove = false;
                    res();
                })
                .start();
        })
        // 播放选中动画
        SlotsFacade.soundMgr.playEffect("wheel_win");
        this.spine_win.node.active = true;
        Global.shakeNode(this.panel, 3, 0.5, this.panel.position);
        await SlotsFacade.delayTime(1.5);
        await this._processWheelResult();
    },

    /**
     * 处理转盘结果
     * @returns {Promise<void>}
     * @private
     */
    async _processWheelResult() {
        Global.SlotsSoundMgr.stopBgm();
        let itemCfg = WheelItemConfig[WheelListCfg[this._respData.result.wheelId-1]];
        switch (itemCfg.type) {
            case WheelItemType.jackpot:
                let jpInfo = this._respData.result.jackpot;
                await SlotsFacade.popup.showWinJPGold(jpInfo.id, jpInfo.value);
                await SlotsFacade.mainPanel.showSceneTransition(4);
                break;
            case WheelItemType.belleBag:
                await SlotsFacade.mainPanel.showSceneTransition(4);
                break;
            case WheelItemType.belleBonus:
                SlotsFacade.dm.belleBonus = this._respData.result.belleBonus;
                SlotsFacade.dm.SetFreeTime(this._respData.result.belleBonus.restCnt);
                SlotsFacade.dm.SetTotalFree(this._respData.result.belleBonus.restCnt);
                SlotsFacade.dm.triggerBelleBonusCoin = SlotsFacade.dm.wheelGame?SlotsFacade.dm.wheelGame.winCoin:0;
                await SlotsFacade.popup.showWinWheelFreeCnt(true);
                await SlotsFacade.mainPanel.showSceneTransition(1);
                break;
            case WheelItemType.freeGame:
                SlotsFacade.dm.SetFreeTime(this._respData.result.freeInfo.freeCnt);
                SlotsFacade.dm.SetTotalFree(this._respData.result.freeInfo.freeCnt);
                await SlotsFacade.popup.showWinWheelFreeCnt(false);
                await SlotsFacade.mainPanel.showSceneTransition(1);
                break;
        }
        this.close({type:itemCfg.type, coin:this._respData.result.winCoin});
    },

    /**
     * 更新卷轴
     * @param dt
     */
    update(dt) {
        if(!this._canMove) {
            return;
        }
        let dist = this.proxy.angle%360/360*this._wheelCfg.totalHeight; // 旋转角度转换成移动距离
        for(let i=0; i<this.items.length; i++) {
            let item =this.items[i];
            let originY = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            originY += dist;
            if(originY<-this._wheelCfg.itemHeight/2) {
                originY += this._wheelCfg.totalHeight;
            }
            item.y = originY;
        }
    },

    _initView() {
        for(let i=0; i<this.items.length; i++) {
            let img = this.items[i].getComponent("ImgSwitchCmp");
            img.node.y = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            let itemCfg = WheelItemConfig[WheelListCfg[i]];
            img.setIndex(itemCfg.iconIndex);
        }
        this.spine_border_idle.node.active = false;
        this.spine_run.node.active = false;
        this.spine_win.node.active = false;
        this.spine_win.node.active = false;
    },

    /**
     * 绑定数据
     * @private
     */
    _bindData() {
        this._canMove = false;
    },

    /**
     * @param cb
     */
    async open(cb, isReconnect) {
        if(!isReconnect) {
            SlotsFacade.soundMgr.playEffect("bell");
            await SlotsFacade.slots.playTriggerAni(SlotsFacade.dm.getSpinData().scatterZJLuXian.indexs);
            SlotsFacade.slots.cleanPlayState();
            Global.SlotsSoundMgr.stopBgm();
            await SlotsFacade.popup.showTriggerWheelAni();
        }
        await SlotsFacade.mainPanel.showSceneTransition(4);
        SlotsFacade.character.hide();
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.soundMgr.playBgm("wheel_bgm");
        cc.vv.gameData.showOtherSysNode(false);
        this.panel.active = true;
        this._cbHandler = cb;
        this._bindData();
        this._initView();

        this._showStartDialog();
    },

    /**
     * 显示开始对话框
     * @private
     */
    async _showStartDialog() {
        // 框体动画
        this.spine_border_start.node.active = true;
        this.spine_border_start.setAnimation(0, "animation", false);
        await new Promise(res=>{
            this.spine_border_start.setCompleteListener(()=>{
                this.spine_border_start.setCompleteListener(null);
                this.spine_border_start.node.active = false;
                res();
            })
        })
        this.spine_border_idle.node.active = true;
        this.spine_border_idle.setAnimation(0, "animation", true);

        // 开始弹窗动画
        // SlotsFacade.soundMgr.playEffect("wheel_open");
        this.startNode.active = true;
        let spine = this.startNode.getChildByName("spine_start").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation3", false);
        spine.addAnimation(0, "animation1", true);
        await new Promise(res=>{
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                res();
            })
        })
        let self = this;
        let clickFunc = function () {
            SlotsFacade.soundMgr.playEffect("wheel_click");
            self.startNode.off(cc.Node.EventType.TOUCH_END);
            spine.setAnimation(0, "animation2", false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                self.startNode.active = false;
                // todo check
                SlotsFacade.dm.reqSubGame({rtype:2})
            });
        }
        cc.vv.gameData.checkAutoPlay( this.startNode, clickFunc);
        this.startNode.on(cc.Node.EventType.TOUCH_END, ()=>{
            this.startNode.stopAllActions()
            clickFunc();
        }, this)
    },

    /**
     * 收到服务器消息
     * @param msg
     */
    onMsg(msg) {
        this._respData = msg.data;
        this._startWheel();
    },

    /**
     * 关闭
     * @returns {Promise<void>}
     */
    async close(ret) {
        this.panel.active = false;
        SlotsFacade.mainPanel.showBg(0);
        cc.vv.gameData.showOtherSysNode(true);
        if(this._cbHandler) {
            this._cbHandler(ret);
        }
    }
})