let CurrRandomIdx = {}; //保存列中当前随机symbol在randomSymbols中的下标
let GetSymbolId = function(reelIdx){
    reelIdx = reelIdx || 0;
    let randomSymbols = SlotsFacade.dm.getGameCfg().randomSymbols;
    if(reelIdx == 0 || reelIdx == 5) {
        randomSymbols = SlotsFacade.dm.getGameCfg().randomSkipWildSymbols;
    }
    if(!CurrRandomIdx.hasOwnProperty(reelIdx.toString())) {
        CurrRandomIdx[reelIdx.toString()] = Math.floor(Math.random()*randomSymbols.length);
    }
    let idx = (CurrRandomIdx[reelIdx.toString()]+1)%randomSymbols.length;
    CurrRandomIdx[reelIdx.toString()] = idx;
    return randomSymbols[idx];
};

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        isEpic:false,   // 是否是respin中的Symbol
        mirror_node:null,  // symbol 镜像父节点
        bonusSymbolMirror:null, // bonus镜像
        label:cc.Label,
        mask:cc.Node,
        isInBonusState:false, // 是否在bonus 状态中
    },

    onLoad() {
        this.label = this.node.getChildByName("label").getComponent(cc.Label);
        this.mask = this.node.getChildByName("mask");
        this.showMask(false);
    },

    /**
     * 显示遮罩
     * @param boo
     */
    showMask(boo) {
        if(!this.mask) {
            return;
        }
        boo = boo || false;
        this.mask.active = boo;
    },

    /**
     * @override
     */
    StartMove:function(){
        this._super();
        this._data = null;
        this.isInBonusState = false;
        this.showMask(false);
    },

    /**
     * @override
     * @param {*} id 
     * @param {*} data 
     */
    ShowById:function(id,data){
        let cfg = cc.vv.gameData.getGameCfg()
        if(id == cfg.blankId) {
            id = this.getRandomIdSkipBonus();
            // if(id == cc.vv.gameData.getGameCfg().bonusId) {
            //     data = {};
            //     data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
            // }
        }
        this._super(id,data);
        this.showLabel(id, data);
        this.showColor();
        if(this.isInBonusState) {
            if(this.GetShowId() == cfg.bonusId) {
                this.showMask(false);
            }else {
                this.showMask(true);
            }
        }
    },

    /**
     * 随机 symbol id
     * @returns {*}
     */
    getRandomId() {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        let randVal = cfg.randomSymbols[randIdx-1];
        return randVal;
    },

    /**
     * 随机 symbol id
     * @returns {*}
     */
    getRandomIdSkipBonus() {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSkipBonusSymbols.length)
        let randVal = cfg.randomSkipBonusSymbols[randIdx-1];
        return randVal;
    },

    /**
     * 显示随机符号
     * @override
     */
    ShowRandomSymbol(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randVal = GetSymbolId(this.GetSymbolReelIdx());
        let data = null;
        if(randVal == cfg.bonusId) {
            data = {};
            data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
        }
        this.ShowById(randVal, data);
    },

    /**
     * 显示金币
     * @param boo
     */
    showLabel(boo) {
        if(boo && this._data && this._data.coin) {
            this.label.node.active = true;
            this.label.string = Global.convertNumToShort(this._data.coin);
        }else {
            this.label.node.active = false;
        }
    },

    /**
     * @override
     */
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    let stopAni = cfg.symbol[id].stop_ani.name;
                    let idleAni = cfg.symbol[id].idle_ani.name;
                    nodeSp.setAnimation(0, stopAni,false);
                    if(idleAni) {
                        nodeSp.addAnimation(0, idleAni, true);
                    }
                }
            }
        }
    },

    /**
     * @override
     * @returns {boolean}
     */
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton);
                if(nodeSp){
                    let triggerAni = cfg.symbol[id].trigger_ani.name;
                    nodeSp.setAnimation(0, triggerAni, cfg.symbol[id].trigger_ani.loop);
                }
            }
            let label = aniNode.getChildByName("label");
            if(this._data && this._data.coin) {
                label.active = true;
                label.getComponent(cc.Label).string = Global.convertNumToShort(this._data.coin);
            }
        }
        return isPlay;
    },

    /**
     * 播放wild出现动画，在随机wild游戏中用到
     */
    playWildAppear() {
        if(this._id != 1) {
            return;
        }
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg()
        this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
        this._showNode.active = true;
        let nodeSp = this._showNode.getComponent(sp.Skeleton)
        if(nodeSp){
            nodeSp.setAnimation(0, "animation1",false);
        }
    },

    showColor() {
        if(this.isEpic && this._showNode) {
            if(this.GetShowId() != SlotsFacade.dm.getGameCfg().bonusId) {
                this._showNode.color = new cc.Color().fromHEX("#3E3E3E");
            }
        }
    },

    hide() {
        if(this._showNode){
            this._showNode.active = false;
        }
    },

    /**
     * 清楚播放状态
     */
    cleanPlayState(){
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    },

    createBonusSymbolMirror() {
        if(!this.mirror_node) {
            return;
        }
        if(this.bonusSymbolMirror) {
            return;
        }
        this.bonusSymbolMirror = new cc.Node();
        this.bonusSymbolMirror.parent = this.mirror_node;
        let s2 = cc.instantiate(this.node.getChildByName("s2"));
        let s3 = cc.instantiate(this.node.getChildByName("s3"));
        s2.parent = this.bonusSymbolMirror;
        s3.parent = this.bonusSymbolMirror;
    },

    /**
     * @override
     */
    // StopMoveEnd() {
    StopMoveDeep() {
        let cfg = SlotsFacade.dm.getGameCfg();
        if(this._id == cfg.bonusId) {
            this.playStopAnimation();
        }
    },

    /**
     * 变换到bonus symbol 在wheel game free bonus 中用到
     */
    changeToBonusSymbol(coin) {
        let cfg = SlotsFacade.dm.getGameCfg();
        this.ShowById(cfg.bonusId, {coin:coin});
        this.label.node.scale = 0;
        cc.tween(this.label.node)
            .to(0.3, {scale:1}, {easing:"backOut"})
            .start();
        let spine = this.node.getChildByName("w3").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation5", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            this.playStopAnimation();
        });
    },

    /**
     * 播放bonus 收集时亮一下的图标
     */
    playBonusLight() {
        let cfg = SlotsFacade.dm.getGameCfg();
        if(this._id != cfg.bonusId) {
            return;
        }
        let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._symbolIdx,this._reelIdx),this._topAniNode);
        if (showNode) {
            let spine = showNode.getChildByName("w3").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation8", false);
            spine.addAnimation(0, "animation7", false);
        }
    },

    /**
     * 设置bonus状态
     */
    setBonusState(boo) {
        boo = boo || false;
        this.isInBonusState = boo;
        if(boo) {
            if(this.GetShowId() == 3) {
                this.showMask(false);
            }else {
                this.showMask(true);
            }
        }
    }
});
