/**
 * 转盘中中的belle free
 */
cc.Class({
    extends: cc.Component,

    properties:{
        panel:cc.Node,
        mask:cc.Node,
        frame_border:cc.Node,
        spine_border:sp.Skeleton,
        wild_node:cc.Node,
        _isEnter:false,
    },

    onLoad() {
        this._symbolTemplate = SlotsFacade.dm.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
    },

    start() {
    },

    enter() {
        this._isEnter = true;
        this.panel.active = true;
    },

    exit() {
        this._isEnter = false;
        this.panel.active = false;
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        if(!this._isEnter) {
            return;
        }
        let wildIdxArr = [];
        let cards = SlotsFacade.dm.getSpinData().resultCards;
        let cfg = SlotsFacade.dm.getGameCfg();
        for(let i=0; i<cards.length; i++) {
            if(cards[i] == cfg.wildId) {
                wildIdxArr.push(i+1);
            }
        }
        let needExtraWild = wildIdxArr.length>3;
        // 角色动画
        await SlotsFacade.character.actionExtraWilds(needExtraWild);
        if(!needExtraWild) {
            return;
        }
        // 框体动画
        this.mask.active = true;
        this.spine_border.node.active = true;
        Global.shakeNode(this.mask, 5, 0.4, this.mask.position);
        Global.shakeNode(this.spine_border.node, 5, 0.4, this.spine_border.node.position);
        await SlotsFacade.delayTime(0.4);
        SlotsFacade.soundMgr.playEffect("wild_appear");
        // 添加wild
        this.wild_node.active = true;
        for(let i=0; i<wildIdxArr.length; i++) {
            let symbol = this.genAWildSymbol(wildIdxArr[i]);
            symbol.playWildAppear();
        }
        await SlotsFacade.delayTime(0.4);
        this.mask.active = false;
        this.spine_border.node.active = false;
    },

    /**
     * 生成一个wild图标
     * @param {*} idx
     */
    genAWildSymbol(idx) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplate)
        node.parent = this.wild_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(0);
        scp.Init(0, this.node);
        scp.ShowById(cfg.wildId);
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return scp;
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        if(!this._isEnter) {
            return;
        }
        this._hideWild();
    },

    /**
     * 隐藏wild
     * @private
     */
    _hideWild() {
        this.wild_node.active = false;
        this.wild_node.removeAllChildren(true);
    },
 })